/// <summary>
/// Represents the current state of 2-step verification
/// </summary>
public partial class PasswordState : Object
{
    /// <summary>
    /// True, if a 2-step verification password is set
    /// </summary>
    public bool HasPassword { get; set; }
    /// <summary>
    /// Hint for the password; may be empty
    /// </summary>
    public string PasswordHint { get; set; } = string.Empty;
    /// <summary>
    /// True, if a recovery email is set
    /// </summary>
    public bool HasRecoveryEmailAddress { get; set; }
    /// <summary>
    /// True, if some Telegram Passport elements were saved
    /// </summary>
    public bool HasPassportData { get; set; }
    /// <summary>
    /// Information about the recovery email address to which the confirmation email was sent; may be null
    /// </summary>
    public EmailAddressAuthenticationCodeInfo? RecoveryEmailAddressCodeInfo { get; set; }
    /// <summary>
    /// Pattern of the email address set up for logging in
    /// </summary>
    public string LoginEmailAddressPattern { get; set; } = string.Empty;
    /// <summary>
    /// If not 0, point in time (Unix timestamp) after which the 2-step verification password can be reset immediately using resetPassword
    /// </summary>
    public int PendingResetDate { get; set; }

    /// <summary>
    /// Represents the current state of 2-step verification
    /// </summary>
    public PasswordState()
    {
    }

    /// <summary>
    /// Represents the current state of 2-step verification
    /// </summary>
    /// <param name="hasPassword">True, if a 2-step verification password is set</param>
    /// <param name="passwordHint">Hint for the password; may be empty</param>
    /// <param name="hasRecoveryEmailAddress">True, if a recovery email is set</param>
    /// <param name="hasPassportData">True, if some Telegram Passport elements were saved</param>
    /// <param name="recoveryEmailAddressCodeInfo">Information about the recovery email address to which the confirmation email was sent; may be null</param>
    /// <param name="loginEmailAddressPattern">Pattern of the email address set up for logging in</param>
    /// <param name="pendingResetDate">If not 0, point in time (Unix timestamp) after which the 2-step verification password can be reset immediately using resetPassword</param>
    public PasswordState(bool hasPassword, string passwordHint, bool hasRecoveryEmailAddress, bool hasPassportData, EmailAddressAuthenticationCodeInfo? recoveryEmailAddressCodeInfo, string loginEmailAddressPattern, int pendingResetDate)
    {
        HasPassword = hasPassword;
        PasswordHint = passwordHint;
        HasRecoveryEmailAddress = hasRecoveryEmailAddress;
        HasPassportData = hasPassportData;
        RecoveryEmailAddressCodeInfo = recoveryEmailAddressCodeInfo;
        LoginEmailAddressPattern = loginEmailAddressPattern;
        PendingResetDate = pendingResetDate;
    }
}
